/// The bytes the C side may touch in memory Map lends for a subresource of `resource` whose rows start `row_pitch`
/// apart and slices `depth_pitch` apart, by the shape's rule from its description; none for a shape no rule covers.
pub(crate) fn mapped_length<A: direct3d_11::Direct3D11>(
    resource: &direct3d_11::ResourceRef<'_, A>,
    subresource: u32,
    row_pitch: u32,
    depth_pitch: u32,
) -> Option<usize> {
    match resource {
        direct3d_11::ResourceRef::Buffer(object) => crate::lengths::mapped_length_buffer(
            &direct3d_11::Buffer::get_desc(*object),
            subresource,
            row_pitch,
            depth_pitch,
        ),
        direct3d_11::ResourceRef::Texture1D(object) => crate::lengths::mapped_length_texture_1d(
            &direct3d_11::Texture1D::get_desc(*object),
            subresource,
            row_pitch,
            depth_pitch,
        ),
        direct3d_11::ResourceRef::Texture2D(object) => crate::lengths::mapped_length_texture_2d(
            &direct3d_11::Texture2D::get_desc(*object),
            subresource,
            row_pitch,
            depth_pitch,
        ),
        direct3d_11::ResourceRef::Texture3D(object) => crate::lengths::mapped_length_texture_3d(
            &direct3d_11::Texture3D::get_desc(*object),
            subresource,
            row_pitch,
            depth_pitch,
        ),
    }
}

/// `mapped_length` for one of our resources: from the description it was made with, when the glue recorded one.
pub(crate) fn mapped_length_found<A: direct3d_11::Direct3D11>(
    resource: &ResourceRefFound<A>,
    subresource: u32,
    row_pitch: u32,
    depth_pitch: u32,
) -> Option<usize> {
    match resource {
        ResourceRefFound::Buffer(found) => {
            let desc = found
                .part::<Recorded<direct3d_11::structures::BufferDesc>>()
                .map_or_else(
                    || direct3d_11::Buffer::get_desc(found.value()),
                    |recorded| recorded.0,
                );
            crate::lengths::mapped_length_buffer(&desc, subresource, row_pitch, depth_pitch).filter(
                |length| crate::lengths::within_served_bound_buffer(&desc, subresource, *length),
            )
        }
        ResourceRefFound::Texture1D(found) => {
            let desc = found
                .part::<Recorded<direct3d_11::structures::Texture1DDesc>>()
                .map_or_else(
                    || direct3d_11::Texture1D::get_desc(found.value()),
                    |recorded| recorded.0,
                );
            crate::lengths::mapped_length_texture_1d(&desc, subresource, row_pitch, depth_pitch)
                .filter(|length| {
                    crate::lengths::within_served_bound_texture_1d(&desc, subresource, *length)
                })
        }
        ResourceRefFound::Texture2D(found) => {
            let desc = found
                .part::<Recorded<direct3d_11::structures::Texture2DDesc>>()
                .map_or_else(
                    || direct3d_11::Texture2D::get_desc(found.value()),
                    |recorded| recorded.0,
                );
            crate::lengths::mapped_length_texture_2d(&desc, subresource, row_pitch, depth_pitch)
                .filter(|length| {
                    crate::lengths::within_served_bound_texture_2d(&desc, subresource, *length)
                })
        }
        ResourceRefFound::Texture3D(found) => {
            let desc = found
                .part::<Recorded<direct3d_11::structures::Texture3DDesc>>()
                .map_or_else(
                    || direct3d_11::Texture3D::get_desc(found.value()),
                    |recorded| recorded.0,
                );
            crate::lengths::mapped_length_texture_3d(&desc, subresource, row_pitch, depth_pitch)
                .filter(|length| {
                    crate::lengths::within_served_bound_texture_3d(&desc, subresource, *length)
                })
        }
    }
}

/// Every module served, for the life of the program: the exports find theirs by type.
static MODULES: Mutex<Vec<Arc<dyn Any + Send + Sync>>> = Mutex::new(Vec::new());

fn module<M: Send + Sync + 'static>() -> Option<Arc<M>> {
    let held = MODULES
        .lock()
        .unwrap_or_else(PoisonError::into_inner)
        .iter()
        .find(|module| module.is::<M>())
        .cloned();
    held.and_then(|module| module.downcast::<M>().ok())
}

/// Serves `module` as the library: the exports C calls, which call it. A module of a type already served
/// is not replaced.
pub fn exports<M>(module: M) -> Library
where
    M: direct3d_11::Direct3D11,
    M: directx_graphics_infrastructure::DirectXGraphicsInfrastructure<
            Buffer = <M as direct3d_11::Direct3D11>::Texture2D,
        >,
{
    directx_graphics_infrastructure_direct::bind_buffer::<<M as direct3d_11::Direct3D11>::Texture2D>(
        texture_2d_interfaces::<<M as direct3d_11::Direct3D11>::Texture2D>,
    );
    {
        let mut modules = MODULES.lock().unwrap_or_else(PoisonError::into_inner);
        if !modules.iter().any(|held| held.is::<M>()) {
            modules.push(Arc::new(module));
        }
    }
    Library {
        d_3d11_create_device: export_d_3d11_create_device::<M>,
        d_3d11_create_device_and_swap_chain: export_d_3d11_create_device_and_swap_chain::<M>,
    }
}

/// The calling glue over the serving glue's own exports of `module`: `module` reached through both glues, as if
/// it were the system's library.
pub fn served<M>(module: M) -> crate::SystemDirect3D11
where
    M: direct3d_11::Direct3D11,
    M: directx_graphics_infrastructure::DirectXGraphicsInfrastructure<
            Buffer = <M as direct3d_11::Direct3D11>::Texture2D,
        >,
{
    let library = exports(module);
    #[expect(
        unsafe_code,
        reason = "our own serving glue's exports, which take what the metadata gives"
    )]
    // SAFETY: each entry of `library` is this crate's serving export of that name, written from the same metadata.
    unsafe {
        crate::SystemDirect3D11::new(library)
    }
}

